template.script:
document.addEventListener('DOMContentLoaded', function () {

    document
        .querySelectorAll('.employee-file-input')
        .forEach(function (fileInput) {

            fileInput.addEventListener(
                'change',
                function () {

                    const displayInput =
                        document.getElementById(
                            'display_' + this.id
                        );

                    if (!displayInput) {
                        return;
                    }

                    if (
                        this.files
                        &&
                        this.files.length > 0
                    ) {

                        if (this.files.length === 1) {

                            displayInput.value =
                                this.files[0].name;

                        } else {

                            displayInput.value =
                                this.files.length
                                + ' files selected';

                        }

                    } else {

                        displayInput.value =
                            'No file selected.';

                    }

                }
            );

        });

});

document.addEventListener('DOMContentLoaded', function () {

    const container =
        document.getElementById('experience_container');

    const addButton =
        document.getElementById('add_experience_btn');

    if (!container || !addButton) {
        return;
    }


    /* =====================================================
       FILE INPUT HANDLER
       ===================================================== */

    function initializeFileInputs(parent) {

        parent
            .querySelectorAll('.employee-file-input')
            .forEach(function (fileInput) {

                if (fileInput.dataset.initialized) {
                    return;
                }

                fileInput.dataset.initialized = '1';

                fileInput.addEventListener(
                    'change',
                    function () {

                        const displayInput =
                            document.getElementById(
                                'display_' + this.id
                            );

                        if (!displayInput) {
                            return;
                        }

                        if (
                            this.files &&
                            this.files.length > 0
                        ) {

                            if (this.files.length === 1) {

                                displayInput.value =
                                    this.files[0].name;

                            } else {

                                displayInput.value =
                                    this.files.length +
                                    ' files selected';

                            }

                        } else {

                            displayInput.value =
                                'No file selected.';

                        }

                    }
                );

            });

    }


    /* =====================================================
       UPDATE EXPERIENCE NUMBERS
       ===================================================== */

    function updateExperienceNumbers() {

        const lines =
            container.querySelectorAll(
                '.experience-line'
            );

        lines.forEach(function (line, index) {

            const number =
                line.querySelector(
                    '.experience-number'
                );

            if (number) {
                number.textContent = index + 1;
            }

        });

    }


    /* =====================================================
       CREATE NEW EXPERIENCE LINE
       ===================================================== */

    function createExperienceLine(index) {

        const wrapper =
            document.createElement('div');

        wrapper.className =
            'experience-line card shadow-sm p-3 mb-3';

        wrapper.setAttribute(
            'data-index',
            index
        );

        wrapper.innerHTML = `

            <input type="hidden"
                   name="experience_id_${index}"
                   value="">

            <div class="d-flex justify-content-between align-items-center mb-3">

                <h6 class="mb-0">
                    Experience
                    <span class="experience-number">
                        ${index + 1}
                    </span>
                </h6>

                <a href="#"
                   class="text-danger remove-experience-line">

                    <i class="fa fa-trash me-1"></i>
                    Remove

                </a>

            </div>


            <div class="row g-3">

                <div class="col-md-6">

                    <label class="form-label">
                        Company Name
                    </label>

                    <input type="text"
                           class="form-control"
                           name="experience_company_name_${index}"
                           placeholder="Enter company name">

                </div>


                <div class="col-md-6">

                    <label class="form-label">
                        Years
                    </label>

                    <input type="number"
                           step="0.01"
                           min="0"
                           class="form-control"
                           name="experience_years_${index}"
                           placeholder="Enter years">

                </div>

            </div>


            <div class="row g-3 mt-1">

                ${createExperienceDocumentField(
                    'bank_statement_id',
                    'Bank Statement',
                    index,
                    false
                )}

                ${createExperienceDocumentField(
                    'salary_slip_id',
                    'Last 3 Month Salary Slip',
                    index,
                    true
                )}

                ${createExperienceDocumentField(
                    'experience_certificate',
                    'Experience Letter',
                    index,
                    false
                )}

                ${createExperienceDocumentField(
                    'joining_letter',
                    'Offer / Joining Letter',
                    index,
                    false
                )}

                ${createExperienceDocumentField(
                    'relieving_letter',
                    'Relieving Letter',
                    index,
                    false
                )}

                ${createExperienceDocumentField(
                    'other_certificate',
                    'Appraisal Letter',
                    index,
                    false
                )}

            </div>
        `;

        return wrapper;
    }


    /* =====================================================
       EXPERIENCE DOCUMENT FIELD
       ===================================================== */

    function createExperienceDocumentField(
        fieldName,
        label,
        index,
        multiple
    ) {

        const multipleAttribute =
            multiple
                ? 'multiple="multiple"'
                : '';

        return `

            <div class="col-md-6">

                <label class="form-label">
                    ${label}
                </label>

                <div class="employee-file-wrapper">

                    <input type="text"
                           class="form-control employee-file-name"
                           id="display_${fieldName}_${index}"
                           value="No file selected."
                           readonly>

                    <label class="employee-file-browse"
                           for="${fieldName}_${index}">
                        Browse...
                    </label>

                    <input type="file"
                           class="employee-file-input"
                           id="${fieldName}_${index}"
                           name="${fieldName}_${index}"
                           accept=".jpg,.jpeg,.png,.pdf"
                           ${multipleAttribute}>

                </div>

            </div>

        `;
    }


    /* =====================================================
       ADD EXPERIENCE
       ===================================================== */

    addButton.addEventListener(
        'click',
        function () {

            const lines =
                container.querySelectorAll(
                    '.experience-line'
                );

            const index = lines.length;

            const newLine =
                createExperienceLine(index);

            container.appendChild(newLine);

            initializeFileInputs(newLine);

            updateExperienceNumbers();

            newLine.scrollIntoView({
                behavior: 'smooth',
                block: 'center'
            });

        }
    );


    /* =====================================================
       REMOVE EXPERIENCE
       ===================================================== */

    container.addEventListener(
        'click',
        function (event) {

            const removeButton =
                event.target.closest(
                    '.remove-experience-line'
                );

            if (!removeButton) {
                return;
            }

            event.preventDefault();

            const line =
                removeButton.closest(
                    '.experience-line'
                );

            if (!line) {
                return;
            }

            const allLines =
                container.querySelectorAll(
                    '.experience-line'
                );

            /*
             * Keep at least one experience line.
             */
            if (allLines.length === 1) {

                alert(
                    'At least one experience line must remain.'
                );

                return;
            }

            if (
                !confirm(
                    'Are you sure you want to remove this experience line?'
                )
            ) {
                return;
            }

            line.remove();

            updateExperienceNumbers();

        }
    );


    /* =====================================================
       INITIALIZE EXISTING FILE INPUTS
       ===================================================== */

    initializeFileInputs(container);

    updateExperienceNumbers();

});
